const normalizeIndustryTitle = (title = '') =>
  title.trim().toLowerCase().replace(/\s*\/\s*/g, '/');

const industryVisualByTitle = new Map(
  industryNavVisuals.map((item) => [normalizeIndustryTitle(item.title), item]),
);

export function getIndustryNavVisual(title = '') {
  return industryVisualByTitle.get(normalizeIndustryTitle(title)) ?? null;
}

export function withIndustryNavVisuals(items = []) {
  return items.map((item) => {
    const visual = getIndustryNavVisual(item.title);
    if (!visual) return item;
    return { ...item, svgClass: visual.svgClass, path: visual.path };
  });
}
